(
  sum by (protocol) (rate(tycho_integration_simulation_get_amount_out_duration_seconds_sum{namespace="$Namespace", protocol=~"$Protocol", container=~".*$Chain.*"}[$__rate_interval])) /
  sum by (protocol) (rate(tycho_integration_simulation_get_amount_out_duration_seconds_count{namespace="$Namespace", protocol=~"$Protocol", container=~".*$Chain.*"}[$__rate_interval]))
) and on(protocol) (
  sum by (protocol) (rate(tycho_integration_simulation_get_amount_out_duration_seconds_count{namespace="$Namespace", protocol=~"$Protocol", container=~".*$Chain.*"}[$__rate_interval])) > 0
)

